 "comment": "Onion Camera v1.7.2 (ANR REGRESSION FIX): real-scene lane, route A live preferred. v1.7.1 ANR'd under this lane (camera-realscene4): shutter tap FAIL, ANR dialog in both later captures, no photo taken. This run proves the fix: longer settle, optional Wait-tap recovery if the ANR dialog appears, shutter tap with corrected fallback geometry (0.45,0.91), photo taken + pulled + opened outside the app, full Back-walk (Settings->viewfinder, MORE->viewfinder, Back on VIDEO stays).",
 "density": 420,
 "height": 2280,
 "image": "google_apis",
 "package": "com.onioncore.camera",
 "permissions": [
  "CAMERA",
  "RECORD_AUDIO"
 ],
 "steps": [
  {
   "do": "record_start"
  },
  {
   "do": "screenshot",
   "label": "00-opening"
  },
  {
   "do": "wait",
   "seconds": 5
  },
  {
   "do": "observe",
   "label": "01-viewfinder"
  },
  {
   "do": "wait",
   "seconds": 12
  },
  {
   "do": "tap_element",
   "text": "Wait",
   "match": "exact",
   "optional": true
  },
  {
   "do": "screenshot",
   "label": "02-viewfinder-later"
  },
  {
   "do": "tap_element",
   "fallback_xy": [
    0.45,
    0.91
   ],
   "match": "exact",
   "text": "Shutter"
  },
  {
   "do": "wait",
   "seconds": 3
  },
  {
   "do": "assert_text",
   "soft": true,
   "text": "Saved"
  },
  {
   "do": "screenshot",
   "label": "03-after-shutter"
  },
  {
   "cmd": "newest=$(adb shell ls -t /sdcard/Pictures/OnionCamera/ 2>/dev/null | head -1 | tr -d '\\015'); if [ -n \"$newest\" ]; then adb pull \"/sdcard/Pictures/OnionCamera/$newest\" \"$RESULTS/taken-photo.jpg\" && api_put \"eyes $ID: taken photo\" \"cloud-pc/storage/eyes/results/$ID/taken-photo.jpg\"; fi",
   "do": "shell"
  },
  {
   "cmd": "if [ -n \"$newest\" ]; then adb shell am start -a android.intent.action.VIEW -d \"file:///sdcard/Pictures/OnionCamera/$newest\" -t \"image/jpeg\" >/dev/null 2>&1; fi",
   "do": "shell"
  },
  {
   "do": "wait",
   "seconds": 3
  },
  {
   "do": "screenshot",
   "label": "04-stock-gallery"
  },
  {
   "do": "tap_element",
   "fallback_xy": [
    0.79,
    0.09
   ],
   "text": "Settings"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "05-settings"
  },
  {
   "do": "back"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "06-after-back-settings"
  },
  {
   "do": "tap_element",
   "fallback_xy": [
    0.79,
    0.83
   ],
   "text": "MORE"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "07-more-grid"
  },
  {
   "do": "back"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "08-after-back-more"
  },
  {
   "do": "tap_element",
   "fallback_xy": [
    0.42,
    0.83
   ],
   "text": "VIDEO"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "09-video-mode"
  },
  {
   "do": "back"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "assert_text",
   "soft": true,
   "text": "Back stays here"
  },
  {
   "do": "observe",
   "label": "10-after-back-video"
  },
  {
   "do": "record_stop",
   "label": "flow"
  }
 ],
